"""Production fingerprint appearance with vendor-shaped ownership and callbacks."""
from pathlib import Path
import ast,subprocess,tempfile
root=Path(__file__).resolve().parents[1]
module=ast.parse((root/'tests/test_statusbar_backend.py').read_text())
sources=ast.literal_eval(next(n.value for n in module.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='sources' for t in n.targets)))
sources={k:v for k,v in sources.items() if k.startswith(('android/','de/'))}
sources['android/view/View.java']=sources['android/view/View.java'].replace('public static final int VISIBLE=', '''private android.graphics.drawable.Drawable background;public boolean failBackgroundApply,failBackgroundRestore;private int pl=1,pt=2,pr=3,pb=4;public android.graphics.drawable.Drawable getBackground(){return background;}public int getPaddingLeft(){return pl;}public int getPaddingTop(){return pt;}public int getPaddingRight(){return pr;}public int getPaddingBottom(){return pb;}public void setPadding(int l,int t,int r,int b){pl=l;pt=t;pr=r;pb=b;}public void setBackground(android.graphics.drawable.Drawable d){XposedBridge.run(this,View.class,"setBackground",new Class<?>[]{android.graphics.drawable.Drawable.class},new Object[]{d},()->{if(failBackgroundRestore&&d!=null)throw new RuntimeException();if(failBackgroundApply&&d==null){failBackgroundApply=false;throw new RuntimeException();}background=d;setPadding(0,0,0,0);});}
public static final int VISIBLE=''')
sources['de/robv/android/xposed/XposedHelpers.java']=sources['de/robv/android/xposed/XposedHelpers.java'].replace('public static Class<?> findClass', 'public static Object getObjectField(Object o,String n){try{var f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}public static Class<?> findClass')
sources['android/widget/ImageView.java']=sources['android/widget/ImageView.java'].replace('private ColorStateList tint;', 'private android.graphics.drawable.Drawable image;public android.graphics.drawable.Drawable getDrawable(){return image;}public void setImageDrawable(android.graphics.drawable.Drawable d){XposedBridge.run(this,ImageView.class,"setImageDrawable",new Class<?>[]{android.graphics.drawable.Drawable.class},new Object[]{d},()->image=d);}public void setImageResource(int id){XposedBridge.run(this,ImageView.class,"setImageResource",new Class<?>[]{int.class},new Object[]{id},()->setImageDrawable(new android.graphics.drawable.Drawable()));}private ColorStateList tint;')
sources.update({
'com/zte/base/Feature.java':'package com.zte.base;public class Feature {public static java.util.HashMap<String,Object> sFeatures=new java.util.HashMap<>();}',
'com/zte/feature/fingerprintlcd/FloatWindowManager.java':'package com.zte.feature.fingerprintlcd;public class FloatWindowManager {public static FloatWindowManager floatWindowManager;public FingerprintUnderLcdFeature mFingerprintUnderLcdFeature;public FloatWindowSensorView floatWindowAuthenticateSensorView;}',
'android/graphics/drawable/Drawable.java':'package android.graphics.drawable;public class Drawable {}',
'com/elitedarkkaiser/nubialy/xposed/FingerprintGlyphDrawable.java':'package com.elitedarkkaiser.nubialy.xposed;public class FingerprintGlyphDrawable extends android.graphics.drawable.Drawable {static final String[] NAMES=com.elitedarkkaiser.nubialy.FingerprintStyles.NAMES;final int style,color;public FingerprintGlyphDrawable(int s,int c){style=s;color=c;}}',
'com/zte/feature/fingerprintlcd/FingerprintUnderLcdFeature.java':'package com.zte.feature.fingerprintlcd;public class FingerprintUnderLcdFeature {public Object mSensorUIService;public android.widget.ImageView mFingerprintIcon=new android.widget.ImageView();public static class Bar {public boolean showing=true;public boolean isKeyguardShowing(){return showing;}}public static class Monitor {public boolean interactive=true;public boolean isDeviceInteractive(){return interactive;}}public Bar mStatusBar=new Bar();public Monitor monitor=new Monitor();public Monitor getKeyguardUpdateMonitor(){return monitor;}public void tryInflateFingerprintIcon(android.view.ViewGroup group){de.robv.android.xposed.XposedBridge.run(this,FingerprintUnderLcdFeature.class,"tryInflateFingerprintIcon",new Class<?>[]{android.view.ViewGroup.class},new Object[]{group},()->{});}public boolean keyguard=true,aod;public int color=-1;public boolean isSensorUIKeyguard(){return keyguard;}public boolean isSensorUIAODStatus(){return aod;}public int getKeyguardColor(){return color;}}',
'com/zte/feature/fingerprintlcd/FloatWindowSensorView.java':'''package com.zte.feature.fingerprintlcd;import de.robv.android.xposed.*;public class FloatWindowSensorView extends android.view.View {public android.widget.ImageView sensorView=new android.widget.ImageView();public boolean enrollState;public void initSensorView(boolean a,boolean b,boolean c,FingerprintUnderLcdFeature f){XposedBridge.run(this,FloatWindowSensorView.class,"initSensorView",new Class<?>[]{boolean.class,boolean.class,boolean.class,FingerprintUnderLcdFeature.class},new Object[]{a,b,c,f},()->{});}public void setEnrollState(boolean value){XposedBridge.run(this,FloatWindowSensorView.class,"setEnrollState",new Class<?>[]{boolean.class},new Object[]{value},()->enrollState=value);}}''',
'com/elitedarkkaiser/nubialy/xposed/FingerprintTest.java':'''package com.elitedarkkaiser.nubialy.xposed;public class FingerprintTest {
static void check(boolean v){if(!v)throw new AssertionError(FingerprintBackend.status());}
public static void main(String[] args){FingerprintBackend.install(FingerprintTest.class.getClassLoader());var owner=new com.zte.feature.fingerprintlcd.FloatWindowSensorView();var image=owner.sensorView;var feature=new com.zte.feature.fingerprintlcd.FingerprintUnderLcdFeature();var stock=new android.graphics.drawable.Drawable();image.setBackground(stock);image.setPadding(1,2,3,4);image.attach();var manager=new com.zte.feature.fingerprintlcd.FloatWindowManager();manager.mFingerprintUnderLcdFeature=feature;manager.floatWindowAuthenticateSensorView=owner;com.zte.feature.fingerprintlcd.FloatWindowManager.floatWindowManager=manager;com.zte.base.Feature.sFeatures.put("fp",feature);
// Discovery must work when all initialization callbacks happened before hooks.

if(args.length>0&&args[0].equals("external")){feature.mSensorUIService=new Object();FingerprintBackend.begin(3,false);check(image.getBackground()==stock);check(FingerprintBackend.status().contains("external SensorService connected"));check(FingerprintBackend.status().contains("captured: 0"));check(FingerprintBackend.end());FingerprintBackend.begin(0,true);check(image.getBackground()==stock);check(FingerprintBackend.end());feature.mSensorUIService=null;FingerprintBackend.begin(3,false);check(image.getBackground() instanceof FingerprintGlyphDrawable);feature.mSensorUIService=new Object();FingerprintBackend.refresh();check(image.getBackground()==stock);check(FingerprintBackend.end());System.out.println("External SensorService left untouched; legacy capture restored on delegation");return;}
if(args.length>0){if(args[0].equals("apply")){image.failBackgroundApply=true;try{FingerprintBackend.begin(0,true);throw new AssertionError();}catch(IllegalStateException expected){}check(image.getBackground()==stock);}else{FingerprintBackend.begin(0,true);image.failBackgroundRestore=true;check(!FingerprintBackend.end());check(FingerprintBackend.status().contains("remaining: 1"));}check(!FingerprintBackend.healthy());try{FingerprintBackend.begin(0,false);throw new AssertionError();}catch(IllegalStateException expected){}System.out.println("Fingerprint failure fence passed: "+args[0]);return;}
FingerprintBackend.begin(0,true);check(image.getBackground()==null);check(image.getVisibility()==0&&image.getAlpha()==1&&image.getPaddingLeft()==1&&image.getPaddingBottom()==4);var latest=new android.graphics.drawable.Drawable();image.setBackground(latest);check(image.getBackground()==null);feature.keyguard=false;FingerprintBackend.refresh();check(image.getBackground()==latest);feature.keyguard=true;FingerprintBackend.refresh();check(image.getBackground()==null);owner.setEnrollState(true);check(image.getBackground()==latest);owner.setEnrollState(false);check(image.getBackground()==null);feature.aod=true;FingerprintBackend.refresh();check(image.getBackground()==latest);feature.aod=false;FingerprintBackend.refresh();check(image.getBackground()==null);check(FingerprintBackend.end());check(image.getBackground()==latest);
for(int style=1;style<com.elitedarkkaiser.nubialy.FingerprintStyles.NAMES.length;style++){FingerprintBackend.begin(style,false);check(image.getBackground() instanceof FingerprintGlyphDrawable);var glyph=(FingerprintGlyphDrawable)image.getBackground();check(glyph.style==style&&glyph.color==-1);image.detach();check(image.getBackground()==latest);image.attach();FingerprintBackend.refresh();check(image.getBackground() instanceof FingerprintGlyphDrawable);check(FingerprintBackend.end());check(image.getBackground()==latest);}
var direct=feature.mFingerprintIcon;direct.attach();direct.setImageDrawable(stock);direct.setBackground(latest);feature.tryInflateFingerprintIcon(new android.view.ViewGroup());FingerprintBackend.begin(0,true);check(direct.getDrawable()==null&&direct.getBackground()==null);check(direct.getVisibility()==0&&direct.getAlpha()==1);direct.setImageResource(10);check(direct.getDrawable()==null);feature.mStatusBar.showing=false;FingerprintBackend.refresh();check(direct.getDrawable()!=null&&direct.getBackground()==latest);var latestImage=direct.getDrawable();feature.mStatusBar.showing=true;feature.monitor.interactive=false;FingerprintBackend.refresh();check(direct.getDrawable()==latestImage);feature.monitor.interactive=true;FingerprintBackend.refresh();check(direct.getDrawable()==null);check(FingerprintBackend.end());check(direct.getDrawable()==latestImage&&direct.getBackground()==latest);FingerprintBackend.begin(3,false);check(direct.getDrawable() instanceof FingerprintGlyphDrawable);check(direct.getBackground()==latest);check(FingerprintBackend.end());check(direct.getDrawable()==latestImage);direct.detach();
var unrelated=new android.widget.ImageView();unrelated.attach();unrelated.setBackground(stock);FingerprintBackend.begin(1,false);check(unrelated.getBackground()==stock);var replacement=new android.widget.ImageView();replacement.attach();owner.sensorView=replacement;FingerprintBackend.refresh();check(image.getBackground()==latest);check(replacement.getBackground() instanceof FingerprintGlyphDrawable);check(FingerprintBackend.end());check(replacement.getBackground()==null);System.out.println("Fingerprint backend passed: graphic-only hiding, four icons, latest stock, preserved visibility/alpha/padding, keyguard/enrollment/AOD gates, detach and replacement restoration");}}
'''
})
with tempfile.TemporaryDirectory(prefix='nubialy-fingerprint-') as work:
    work=Path(work)
    for name,content in sources.items():
        p=work/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
    files=[str(p) for p in work.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/xposed/FingerprintBackend.java')]
    files.append(str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/FingerprintStyles.java'))
    subprocess.run(['java','com.sun.tools.javac.Main','-d',str(work/'classes'),*files],check=True)
    for mode in [[],['apply'],['restore'],['external']]:subprocess.run(['java','-cp',str(work/'classes'),'com.elitedarkkaiser.nubialy.xposed.FingerprintTest',*mode],check=True)
